"use client";

import { cn } from "../lib/cn";
import { MOTION_DEFAULTS, type ModalMotion } from "../lib/motion";
import { exitDurationForMotion, usePresence } from "../lib/presence";
import {
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react";
import { createPortal } from "react-dom";

export type { ModalMotion as CommandPaletteMotion };

export type CommandItem = {
  id: string;
  label: string;
  description?: string;
  /** Extra searchable text (not shown). */
  keywords?: string;
  /** Optional group heading key. */
  group?: string;
  icon?: ReactNode;
  disabled?: boolean;
  onSelect?: () => void;
};

export type CommandPaletteProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  items: CommandItem[];
  /** Called after item select (before close). */
  onSelect?: (item: CommandItem) => void;
  placeholder?: string;
  emptyMessage?: string;
  /** Accessible dialog name. */
  label?: string;
  motion?: ModalMotion;
  closeOnBackdrop?: boolean;
  closeOnEscape?: boolean;
  className?: string;
  panelClassName?: string;
};

function filterItems(items: CommandItem[], query: string): CommandItem[] {
  const q = query.trim().toLowerCase();
  if (!q) return items;
  return items.filter((item) => {
    const hay = [
      item.label,
      item.description ?? "",
      item.keywords ?? "",
      item.group ?? "",
    ]
      .join(" ")
      .toLowerCase();
    return hay.includes(q);
  });
}

function groupItems(items: CommandItem[]): { group: string | null; items: CommandItem[] }[] {
  const order: string[] = [];
  const map = new Map<string, CommandItem[]>();
  const ungrouped: CommandItem[] = [];

  for (const item of items) {
    if (!item.group) {
      ungrouped.push(item);
      continue;
    }
    if (!map.has(item.group)) {
      map.set(item.group, []);
      order.push(item.group);
    }
    map.get(item.group)!.push(item);
  }

  const result: { group: string | null; items: CommandItem[] }[] = [];
  if (ungrouped.length) result.push({ group: null, items: ungrouped });
  for (const g of order) {
    result.push({ group: g, items: map.get(g)! });
  }
  return result;
}

/**
 * Molecule — CommandPalette (minimal)
 * Search + list + keyboard select. Modal shell. No fuzzy ranking lib.
 */
export function CommandPalette({
  open,
  onOpenChange,
  items,
  onSelect,
  placeholder = "Type a command or search…",
  emptyMessage = "No results",
  label = "Command palette",
  motion = MOTION_DEFAULTS.modal,
  closeOnBackdrop = true,
  closeOnEscape = true,
  className,
  panelClassName,
}: CommandPaletteProps) {
  const labelId = useId();
  const listId = useId();
  const inputRef = useRef<HTMLInputElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  const previouslyFocused = useRef<HTMLElement | null>(null);
  const [portalReady, setPortalReady] = useState(false);
  const [query, setQuery] = useState("");
  const [activeIndex, setActiveIndex] = useState(0);

  const { mounted, exiting, state } = usePresence(open, {
    durationMs: exitDurationForMotion(motion),
  });

  const filtered = useMemo(() => filterItems(items, query), [items, query]);
  const groups = useMemo(() => groupItems(filtered), [filtered]);
  /** Same order as rendered options (ungrouped first, then group order). */
  const flatItems = useMemo(
    () => groups.flatMap((g) => g.items),
    [groups],
  );

  useEffect(() => {
    setPortalReady(true);
  }, []);

  useEffect(() => {
    if (!open) return;
    previouslyFocused.current =
      document.activeElement instanceof HTMLElement
        ? document.activeElement
        : null;
    setQuery("");
    setActiveIndex(0);
  }, [open]);

  useEffect(() => {
    if (!mounted) return;
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.body.style.overflow = previousOverflow;
    };
  }, [mounted]);

  useEffect(() => {
    if (mounted) return;
    previouslyFocused.current?.focus?.();
  }, [mounted]);

  useEffect(() => {
    if (!open || exiting) return;
    const t = window.setTimeout(() => inputRef.current?.focus(), 0);
    return () => window.clearTimeout(t);
  }, [open, exiting]);

  // Clamp active index when filter shrinks.
  useEffect(() => {
    if (activeIndex >= flatItems.length) {
      setActiveIndex(Math.max(0, flatItems.length - 1));
    }
  }, [flatItems.length, activeIndex]);

  function selectItem(item: CommandItem) {
    if (item.disabled || exiting) return;
    item.onSelect?.();
    onSelect?.(item);
    onOpenChange(false);
  }

  useEffect(() => {
    if (!open || exiting) return;

    function onKeyDown(event: KeyboardEvent) {
      if (closeOnEscape && event.key === "Escape") {
        event.preventDefault();
        onOpenChange(false);
        return;
      }

      if (event.key === "ArrowDown") {
        event.preventDefault();
        if (flatItems.length === 0) return;
        setActiveIndex((i) => {
          let next = i;
          for (let step = 0; step < flatItems.length; step++) {
            next = (next + 1) % flatItems.length;
            if (!flatItems[next]?.disabled) return next;
          }
          return i;
        });
        return;
      }

      if (event.key === "ArrowUp") {
        event.preventDefault();
        if (flatItems.length === 0) return;
        setActiveIndex((i) => {
          let next = i;
          for (let step = 0; step < flatItems.length; step++) {
            next = (next - 1 + flatItems.length) % flatItems.length;
            if (!flatItems[next]?.disabled) return next;
          }
          return i;
        });
        return;
      }

      if (event.key === "Enter") {
        event.preventDefault();
        const item = flatItems[activeIndex];
        if (item) selectItem(item);
        return;
      }

      if (event.key !== "Tab") return;
      const panel = panelRef.current;
      if (!panel) return;
      const FOCUSABLE =
        'button:not([disabled]), [href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])';
      const nodes = Array.from(
        panel.querySelectorAll<HTMLElement>(FOCUSABLE),
      ).filter((el) => !el.hasAttribute("disabled") && el.tabIndex !== -1);
      if (nodes.length === 0) {
        event.preventDefault();
        return;
      }
      const first = nodes[0]!;
      const last = nodes[nodes.length - 1]!;
      const active = document.activeElement;
      if (event.shiftKey) {
        if (active === first || !panel.contains(active)) {
          event.preventDefault();
          last.focus();
        }
      } else if (active === last || !panel.contains(active)) {
        event.preventDefault();
        first.focus();
      }
    }

    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [open, exiting, closeOnEscape, onOpenChange, flatItems, activeIndex]);

  // Scroll active option into view.
  useEffect(() => {
    if (!open) return;
    const id = flatItems[activeIndex]?.id;
    if (!id) return;
    document
      .getElementById(`${listId}-opt-${id}`)
      ?.scrollIntoView({ block: "nearest" });
  }, [activeIndex, flatItems, listId, open]);

  if (!mounted || !portalReady) return null;

  const activeItem = flatItems[activeIndex];
  const activeDescendant = activeItem
    ? `${listId}-opt-${activeItem.id}`
    : undefined;

  let optionIndex = -1;

  return createPortal(
    <div
      className={cn("sg-command-root", className)}
      role="presentation"
      data-motion={motion}
      data-state={state}
    >
      <button
        type="button"
        className="sg-command-backdrop"
        aria-label="Close command palette"
        tabIndex={exiting ? -1 : undefined}
        onClick={() => {
          if (exiting) return;
          if (closeOnBackdrop) onOpenChange(false);
        }}
      />
      <div
        ref={panelRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby={labelId}
        tabIndex={-1}
        className={cn(
          "sg-command-panel",
          "sg-surface-glass-elevated",
          panelClassName,
        )}
        data-state={state}
        data-motion={motion}
      >
        <h2 id={labelId} className="sg-command-sr-only">
          {label}
        </h2>

        <div className="sg-command-search">
          <span className="sg-command-search-icon" aria-hidden="true">
            ⌕
          </span>
          <input
            ref={inputRef}
            type="text"
            className="sg-command-input"
            role="combobox"
            aria-expanded="true"
            aria-controls={listId}
            aria-autocomplete="list"
            aria-activedescendant={activeDescendant}
            placeholder={placeholder}
            value={query}
            disabled={exiting}
            onChange={(e) => {
              setQuery(e.target.value);
              setActiveIndex(0);
            }}
          />
          <kbd className="sg-command-kbd">esc</kbd>
        </div>

        <div
          id={listId}
          role="listbox"
          aria-label={label}
          className="sg-command-list"
        >
          {flatItems.length === 0 ? (
            <div className="sg-command-empty" role="presentation">
              {emptyMessage}
            </div>
          ) : (
            groups.map((g) => (
              <div
                key={g.group ?? "__ungrouped"}
                className="sg-command-group"
                role="presentation"
              >
                {g.group ? (
                  <div className="sg-command-group-label" role="presentation">
                    {g.group}
                  </div>
                ) : null}
                {g.items.map((item) => {
                  optionIndex += 1;
                  const index = optionIndex;
                  const active = index === activeIndex;
                  return (
                    <div
                      key={item.id}
                      id={`${listId}-opt-${item.id}`}
                      role="option"
                      aria-selected={active}
                      aria-disabled={item.disabled || undefined}
                      className={cn(
                        "sg-command-item",
                        active && "sg-command-item-active",
                        item.disabled && "sg-command-item-disabled",
                      )}
                      data-active={active || undefined}
                      onMouseEnter={() => {
                        if (!item.disabled) setActiveIndex(index);
                      }}
                      onClick={() => selectItem(item)}
                    >
                      {item.icon ? (
                        <span className="sg-command-item-icon" aria-hidden>
                          {item.icon}
                        </span>
                      ) : null}
                      <span className="sg-command-item-text">
                        <span className="sg-command-item-label">
                          {item.label}
                        </span>
                        {item.description ? (
                          <span className="sg-command-item-desc">
                            {item.description}
                          </span>
                        ) : null}
                      </span>
                    </div>
                  );
                })}
              </div>
            ))
          )}
        </div>
      </div>
    </div>,
    document.body,
  );
}

/** Values allowed in `cn(...)` — only strings survive. */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
type ClassValue = string | false | null | undefined | 0 | 0n | boolean;

/**
 * Tiny class merger — no runtime deps.
 * Prefer this over pulling tailwind-merge until we need conflict resolution.
 */
export function cn(...parts: ClassValue[]): string {
  return parts.filter((part): part is string => typeof part === "string" && part.length > 0).join(" ");
}

/** Shared visual “look” languages across controls. */

export type ButtonLook = "solid" | "soft" | "glass" | "gradient" | "neon";

export type RadioLook = "dot" | "card" | "chip";

export type CheckboxLook = "box" | "card" | "pill";

export type SwitchLook = "track" | "ios" | "minimal";

export type BadgeLook = "soft" | "solid" | "outline" | "glow";

export type FieldLook = "solid" | "underline" | "filled" | "ghost";

export type SelectLook = "solid" | "soft" | "glass" | "gradient";

export type TabsLook = "pill" | "underline" | "segmented";

export type AvatarLook = "circle" | "rounded" | "soft";

export type TooltipLook = "frost" | "solid" | "accent";

export type CardLook = "flat" | "raised" | "outline" | "glow";

/** NumberInput shell + stepper language */
export type NumberInputLook = "soft" | "solid" | "outline" | "ghost";

/** Slider track / thumb language */
export type SliderLook = "soft" | "solid" | "glass" | "accent";

/** FileField trigger surface */
export type FileFieldLook = "solid" | "soft" | "dashed" | "ghost";

/** Progress track / fill language */
export type ProgressLook = "soft" | "solid" | "glass" | "accent" | "striped";

/** StatusDot chrome language (color still from status / color) */
export type StatusDotLook = "soft" | "solid" | "outline" | "glow";

/** Chip surface language */
export type ChipLook = "soft" | "solid" | "outline" | "glass" | "glow";

/** CloseButton chrome */
export type CloseButtonLook = "ghost" | "soft" | "solid" | "danger";

/**
 * Collapsible / Accordion disclosure surface
 * soft = frost card · solid = long content · glass = chrome · outline = border only · ghost = flush list
 */
export type CollapsibleLook = "soft" | "solid" | "glass" | "outline" | "ghost";

export type AccordionLook = CollapsibleLook;

/** Breadcrumb chrome: plain path · soft tray · pill chips */
export type BreadcrumbLook = "plain" | "soft" | "pill";

/** Pagination control chrome */
export type PaginationLook = "soft" | "solid" | "ghost" | "glass";

/** EmptyState surface */
export type EmptyStateLook = "solid" | "soft" | "outline";

/**
 * Stepper language
 * soft = frost track · solid = solid rail · outline = line only
 * dots = progress line + large dots · pills = segmented chip row
 */
export type StepperLook = "soft" | "solid" | "outline" | "dots" | "pills";

/**
 * Toolbar strip
 * soft | solid | glass | ghost | accent (accent edge rail)
 */
export type ToolbarLook = "soft" | "solid" | "glass" | "ghost" | "accent";

/** List host surface */
export type ListLook = "soft" | "solid" | "outline" | "ghost" | "inset";

/**
 * Stat metric tile
 * solid | soft | glass | outline | accent (left rail)
 */
export type StatLook = "solid" | "soft" | "glass" | "outline" | "accent";

/** PageHeader chrome: plain flush · soft frost · solid panel · glass chrome */
export type PageHeaderLook = "plain" | "soft" | "solid" | "glass";

/** SettingsSection panel chrome */
export type SettingsSectionLook = "soft" | "solid" | "glass" | "plain";

/**
 * DataTable surface language
 * soft = frost · solid = panel · glass = chrome · outline = border · ghost = flush
 */
export type DataTableLook = "soft" | "solid" | "glass" | "outline" | "ghost";

/**
 * Motion recipes — component-specific animation menus.
 * Parallel to `look` (visual surface). Always pair with `prefers-reduced-motion`.
 *
 * Defaults match the pre-motion global micro-interactions so existing UIs
 * keep the same feel when no prop is passed.
 */

/** Shared “off” token used on every control. */
export type MotionNone = "none";

export type ButtonMotion = MotionNone | "lift" | "press" | "sheen" | "ripple";

export type CheckboxMotion = MotionNone | "pop" | "draw" | "fade-in" | "bounce";

export type RadioMotion = MotionNone | "pop" | "dot-scale" | "ring-expand";

export type SwitchMotion = MotionNone | "snap" | "spring" | "elastic";

export type FieldMotion = MotionNone | "ring" | "underline-grow" | "glow";

export type SelectMotion = MotionNone | "fade" | "scale" | "slide-down";

export type TooltipMotion = MotionNone | "fade" | "scale" | "slide";

export type BadgeMotion = MotionNone | "pulse" | "pop-in" | "shimmer";

export type AvatarMotion = MotionNone | "lift" | "ring-pulse" | "status-ping";

/**
 * Tabs indicator + content enter.
 * - none: instant active swap
 * - fade: soft cross-fade on active chrome / content
 * - slide: moving pill or underline indicator (content still fades)
 */
export type TabsMotion = MotionNone | "fade" | "slide";

export type ModalMotion = MotionNone | "scale" | "fade" | "slide-up";

export type ToastMotion = MotionNone | "slide-in" | "pop";

export type CardMotion = MotionNone | "lift" | "glow-pulse";

/** Popover / DropdownMenu panel enter (same recipe set as Select menu). */
export type PopoverMotion = MotionNone | "fade" | "scale" | "slide-down";

export type DropdownMenuMotion = MotionNone | "fade" | "scale" | "slide-down";

/** ContextMenu panel — same recipes as DropdownMenu / Popover. */
export type ContextMenuMotion = MotionNone | "fade" | "scale" | "slide-down";

/** DatePicker calendar panel — same recipes as Select. */
export type DatePickerMotion = MotionNone | "fade" | "scale" | "slide-down";

/** Collapsible / Accordion panel open motion. */
export type CollapsibleMotion = MotionNone | "fade" | "height";

export type AccordionMotion = CollapsibleMotion;

/** Sheet edge panel enter/exit. */
export type SheetMotion = MotionNone | "slide" | "fade";

/** HoverCard panel (Popover family). */
export type HoverCardMotion = MotionNone | "fade" | "scale" | "slide-down";

/** Defaults — preserve current product feel. */
export const MOTION_DEFAULTS = {
  button: "lift",
  checkbox: "pop",
  radio: "pop",
  switch: "spring",
  field: "ring",
  select: "scale",
  tooltip: "scale",
  badge: "none",
  avatar: "lift",
  tabs: "slide",
  modal: "scale",
  toast: "slide-in",
  card: "lift",
  popover: "scale",
  dropdownMenu: "scale",
  contextMenu: "scale",
  datePicker: "scale",
  collapsible: "height",
  accordion: "height",
  sheet: "slide",
  hoverCard: "scale",
} as const satisfies Record<string, string>;

"use client";

import { useEffect, useState } from "react";

/**
 * Unmount delay so CSS exit animations can finish.
 * Keep in sync with token exit durations (~`--sg-duration-normal` / motion-med).
 */
export const EXIT_DURATION_MS = 200;

export type PresenceOptions = {
  /** 0 = unmount immediately (motion="none" or reduced-motion). */
  durationMs?: number;
};

function prefersReducedMotion(): boolean {
  if (typeof window === "undefined") return false;
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

/** Map motion recipe → exit hold time. */
export function exitDurationForMotion(motion: string | undefined): number {
  if (motion === "none") return 0;
  if (prefersReducedMotion()) return 0;
  return EXIT_DURATION_MS;
}

/**
 * Keep a node mounted while `open` is true **and** briefly after it becomes false
 * so exit keyframes can play. Mirrors Radix presence / `data-state` pattern.
 */
export function usePresence(open: boolean, options?: PresenceOptions) {
  const durationMs = options?.durationMs ?? EXIT_DURATION_MS;
  const [mounted, setMounted] = useState(open);
  const [exiting, setExiting] = useState(false);

  useEffect(() => {
    if (open) {
      setMounted(true);
      setExiting(false);
      return;
    }

    if (!mounted) return;

    if (durationMs <= 0) {
      setMounted(false);
      setExiting(false);
      return;
    }

    setExiting(true);
    const id = window.setTimeout(() => {
      setMounted(false);
      setExiting(false);
    }, durationMs);

    return () => window.clearTimeout(id);
  }, [open, durationMs, mounted]);

  return {
    /** Still in the DOM (open or playing exit). */
    mounted,
    /** Exit animation should run. */
    exiting,
    /** For `data-state`: open while interactive, closed while exiting. */
    state: (open && !exiting ? "open" : "closed") as "open" | "closed",
  };
}
